ALTER TABLE public.appointments ADD COLUMN IF NOT EXISTS check_in_at timestamptz, ADD COLUMN IF NOT EXISTS check_in_note text, ADD COLUMN IF NOT EXISTS check_in_photo_url text, ADD COLUMN IF NOT EXISTS check_in_by uuid REFERENCES public.profiles(id), ADD COLUMN IF NOT EXISTS check_out_at timestamptz, ADD COLUMN IF NOT EXISTS check_out_note text, ADD COLUMN IF NOT EXISTS check_out_photo_url text, ADD COLUMN IF NOT EXISTS check_out_by uuid REFERENCES public.profiles(id);
ALTER TABLE public.workshops ADD COLUMN IF NOT EXISTS is_own_yard boolean NOT NULL DEFAULT false;
ALTER TABLE public.status_options ADD COLUMN IF NOT EXISTS show_in_yard boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS show_external boolean NOT NULL DEFAULT false;
CREATE TABLE public.yard_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), timer_green_hours numeric DEFAULT 4, timer_yellow_hours numeric DEFAULT 24, check_in_required boolean DEFAULT true, check_out_required boolean DEFAULT true, photo_capture_enabled boolean DEFAULT false, photo_upload_enabled boolean DEFAULT false, photo_max_mb integer DEFAULT 10, notification_sound_enabled boolean DEFAULT true, polling_seconds integer DEFAULT 30 CHECK(polling_seconds>=15), toast_duration_ms integer DEFAULT 4000, new_highlight_minutes integer DEFAULT 5, editable_fields jsonb DEFAULT '["status","note","operator","current_deadline","contact","contact_number","issue"]', updated_at timestamptz DEFAULT now(), updated_by uuid REFERENCES public.profiles(id));
GRANT SELECT,INSERT,UPDATE ON public.yard_settings TO authenticated; GRANT ALL ON public.yard_settings TO service_role;
ALTER TABLE public.yard_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY yard_read ON public.yard_settings FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid()));
CREATE POLICY yard_master ON public.yard_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'master')) WITH CHECK(public.has_role(auth.uid(),'master'));
CREATE TABLE public.check_in_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL REFERENCES public.appointments(id), os_number integer, type text NOT NULL CHECK(type IN('entrada','saida')), occurred_at timestamptz NOT NULL DEFAULT now(), note text, photo_url text, performed_by uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.check_in_records TO authenticated; GRANT ALL ON public.check_in_records TO service_role;
ALTER TABLE public.check_in_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY check_read ON public.check_in_records FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.appointments a WHERE a.id=appointment_id));
CREATE POLICY check_write ON public.check_in_records FOR INSERT TO authenticated WITH CHECK(performed_by=auth.uid() AND EXISTS(SELECT 1 FROM public.appointments a WHERE a.id=appointment_id AND a.archived_at IS NULL));
CREATE FUNCTION public.yard_status_durations() RETURNS TABLE(appointment_id uuid,last_status_change_at timestamptz) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT a.id,max(e.changed_at) FROM public.appointments a LEFT JOIN public.edit_log e ON e.appointment_id=a.id AND e.field_changed='status' WHERE a.archived_at IS NULL GROUP BY a.id $$;
REVOKE ALL ON FUNCTION public.yard_status_durations() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.yard_status_durations() TO authenticated;
ALTER TABLE public.vehicles ADD COLUMN IF NOT EXISTS extra_data jsonb NOT NULL DEFAULT '{}';
ALTER TABLE public.ordens_servico ADD COLUMN IF NOT EXISTS vehicle_id uuid REFERENCES public.vehicles(id);
CREATE TABLE public.vehicle_screen_access(user_id uuid PRIMARY KEY, allowed boolean NOT NULL DEFAULT true, updated_by uuid REFERENCES public.profiles(id), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.vehicle_screen_access TO authenticated; GRANT ALL ON public.vehicle_screen_access TO service_role;
ALTER TABLE public.vehicle_screen_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY access_read ON public.vehicle_screen_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'master'));
CREATE POLICY access_master ON public.vehicle_screen_access FOR ALL TO authenticated USING(public.has_role(auth.uid(),'master')) WITH CHECK(public.has_role(auth.uid(),'master'));
CREATE FUNCTION public.can_view_vehicles(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid) AND (public.has_role(_uid,'master') OR coalesce((SELECT allowed FROM public.vehicle_screen_access WHERE user_id=_uid),true)) $$;
REVOKE ALL ON FUNCTION public.can_view_vehicles(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_view_vehicles(uuid) TO authenticated,service_role;
DROP POLICY "Users with access read vehicles" ON public.vehicles;
DROP POLICY "Managers write vehicles" ON public.vehicles;
CREATE POLICY vehicle_read ON public.vehicles FOR SELECT TO authenticated USING(public.can_view_vehicles(auth.uid()));
CREATE POLICY vehicle_insert ON public.vehicles FOR INSERT TO authenticated WITH CHECK(public.can_view_vehicles(auth.uid()) AND (public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'gerente')));
CREATE POLICY vehicle_update ON public.vehicles FOR UPDATE TO authenticated USING(public.can_view_vehicles(auth.uid()) AND (public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'gerente'))) WITH CHECK(public.can_view_vehicles(auth.uid()) AND (public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'gerente')));
CREATE TABLE public.workshop_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid NOT NULL REFERENCES public.appointments(id), workshop_id uuid NOT NULL REFERENCES public.workshops(id), os_id uuid NOT NULL REFERENCES public.ordens_servico(id), entered_at timestamptz NOT NULL DEFAULT now(), left_at timestamptz, actor_id uuid REFERENCES public.profiles(id));
GRANT SELECT ON public.workshop_movements TO authenticated; GRANT ALL ON public.workshop_movements TO service_role;
ALTER TABLE public.workshop_movements ENABLE ROW LEVEL SECURITY;
CREATE POLICY movement_read ON public.workshop_movements FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.appointments a WHERE a.id=appointment_id));
CREATE INDEX movement_appointment ON public.workshop_movements(appointment_id,entered_at DESC);
CREATE FUNCTION public.os_forward_appointment(_appointment_id uuid,_workshop_id uuid,_km integer,_store_id integer,_tipo_id integer,_centro_custo_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE a public.appointments; w public.workshops; o public.ordens_servico; r jsonb; BEGIN
IF auth.uid() IS NULL OR NOT(public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'gerente') OR public.has_role(auth.uid(),'atendimento')) THEN RAISE EXCEPTION 'Seu perfil não pode encaminhar veículos'; END IF;
SELECT * INTO a FROM public.appointments WHERE id=_appointment_id AND archived_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Agendamento não encontrado ou sem acesso'; END IF;
SELECT * INTO w FROM public.workshops WHERE id=_workshop_id AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Escolha uma oficina ativa'; END IF;
IF public.norm_plate(a.plate)='' OR _km IS NULL OR _km<0 OR NOT EXISTS(SELECT 1 FROM public.sgloc_stores WHERE store_id=_store_id) OR NOT EXISTS(SELECT 1 FROM public.os_tipos WHERE id=_tipo_id AND active) OR NOT EXISTS(SELECT 1 FROM public.centros_custo WHERE id=_centro_custo_id AND active) THEN RAISE EXCEPTION 'Preencha placa, KM, loja, tipo e centro de custo válidos'; END IF;
SELECT * INTO o FROM public.ordens_servico WHERE appointment_id=a.id AND archived_at IS NULL AND closed_at IS NULL AND status_id NOT IN(3,7) ORDER BY created_at DESC LIMIT 1;
IF o.id IS NULL THEN r:=public.os_create(a.plate,_km,_store_id,w.id,_tipo_id,_centro_custo_id,_appointment_id=>a.id,_obs1=>a.issue); SELECT * INTO o FROM public.ordens_servico WHERE id=(r->>'id')::uuid; ELSE PERFORM public.os_update(o.id,jsonb_build_object('workshop_id',w.id)); END IF;
UPDATE public.ordens_servico SET vehicle_id=(SELECT id FROM public.vehicles WHERE public.norm_plate(plate)=public.norm_plate(a.plate) LIMIT 1) WHERE id=o.id;
UPDATE public.appointments SET workshop=w.name,forwarded_workshop_id=w.id,os_number=o.numero WHERE id=a.id;
PERFORM public.record_workshop_movement(a.id,w.id,o.id);
RETURN jsonb_build_object('id',o.id,'numero',o.numero,'workshop',w.name); END $$;
CREATE FUNCTION public.record_workshop_movement(_appointment uuid,_workshop uuid,_os uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT(public.has_role(auth.uid(),'master') OR public.has_role(auth.uid(),'gerente') OR public.has_role(auth.uid(),'atendimento')) OR NOT EXISTS(SELECT 1 FROM public.appointments WHERE id=_appointment AND forwarded_workshop_id=_workshop AND archived_at IS NULL) OR NOT EXISTS(SELECT 1 FROM public.ordens_servico WHERE id=_os AND appointment_id=_appointment AND workshop_id=_workshop) THEN RAISE EXCEPTION 'Encaminhamento inválido'; END IF;
IF EXISTS(SELECT 1 FROM public.workshop_movements WHERE appointment_id=_appointment AND workshop_id=_workshop AND os_id=_os AND left_at IS NULL) THEN RETURN; END IF;
UPDATE public.workshop_movements SET left_at=now() WHERE appointment_id=_appointment AND left_at IS NULL;
INSERT INTO public.workshop_movements(appointment_id,workshop_id,os_id,actor_id) VALUES(_appointment,_workshop,_os,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.record_workshop_movement(uuid,uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.record_workshop_movement(uuid,uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.os_forward_appointment(uuid,uuid,integer,integer,integer,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.os_forward_appointment(uuid,uuid,integer,integer,integer,uuid) TO authenticated;